// Client ownership, required input, checkboxes and phase ordering cannot be bypassed.
test("out-of-order, wrong-client and incomplete actions are no-ops", () => {
  const initial = createMobileState();
  assert.equal(step(initial, "assign", "App 端"), initial);
  assert.equal(step(initial, "draft", "网页端"), initial);
  let assigned = step(initial, "assign", "网页端");
  assert.equal(step(assigned, "assign", "网页端"), assigned);
  assert.equal(step(assigned, "review", "网页端"), assigned);
  assert.equal(step(assigned, "review", "App 端", "     "), assigned);
  let reviewed = step(assigned, "review", "App 端");
  assert.equal(step(reviewed, "draft", "网页端", "太短"), reviewed);
  const drafted = step(reviewed, "draft", "网页端");
  assert.equal(step(drafted, "approve", "App 端", "", false), drafted);
  assert.equal(step(drafted, "approve", "网页端", "", true), drafted);
  const stale = {
    ...drafted,
    reports: drafted.reports.map((r) => ({ ...r, stale: true })),
  };
  assert.equal(step(stale, "approve", "App 端", "", true), stale);
});

// A reviewer can return the work for more evidence and the next assignment retains that context.
test("returned reviews preserve feedback and can be assigned again", () => {
  let state = step(createMobileState(), "assign", "网页端");
  state = step(state, "return", "App 端", "请补充门店与现场材料后再次提交。");
  assert.equal(state.collaboration.phase, "identified");
  assert.equal(state.statuses["ALT-1103-001"], "待确认");
  assert.match(state.collaboration.feedback, /补充门店/);
  state = step(state, "assign", "网页端");
  assert.equal(state.collaboration.phase, "assigned");
  assert.equal(state.collaboration.events.length, 3);
});

// An earlier mobile snapshot should gain an empty workflow without losing existing choices.
test("earlier mobile state migrates without resetting report versions or follows", () => {
  const old = createMobileState() as Partial<MobileState>;
  delete old.collaboration;
  old.following = ["TOP-005"];
  const migrated = parseMobileState(JSON.stringify(old));
  assert.deepEqual(migrated.following, ["TOP-005"]);
  assert.equal(migrated.collaboration.phase, "identified");
});
